DO $import$
DECLARE
  payload jsonb := $json$[{"id":"5a7466b9-2422-5d5d-9460-ee61b2002f13","username":"rahul.iyer","display_name":"Rahul Iyer","first_name":"Rahul","last_name":"Iyer","headline":"Producer & mix engineer for indie, electronic and film-adjacent records.","bio":"I build records around the vocal — warm low end, wide stereo, nothing overproduced. Started as a live keys player with touring indie acts, moved into production in 2017 and now split time between my room in Indiranagar and tracking days at Yash Raj Sound. I work fast on references, send stems labelled, and stay on a project through mastering hand-off. Comfortable with Hindi, Tamil and English lyric sessions.","city":"Bengaluru","state":"Karnataka","country":"India","roles":["producer","mixing_engineer","keyboardist"],"instruments":["keyboard"],"genres":["rnb","bollywood"],"languages":["en","ta","kn","hi"],"specialisations":["producer:Vocal production","producer:Analog summing","producer:Hybrid mixing","producer:Stem mastering prep"],"avatar_url":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80","cover_url":"https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?auto=format&fit=crop&w=900&q=80","availability":"Session Work","experience_level":"10+","links":{"spotify":"Rahul Iyer","soundcloud":"rahuliyersound","youtube":"@rahuliyer","instagram":"@rahul.iyer"},"is_verified":true,"is_available":true,"trust_badges":["verified_artist"],"visibility":"public"},{"id":"0662ace1-0642-5590-832f-f55fa23438f1","username":"meher.kaur","display_name":"Meher Kaur","first_name":"Meher","last_name":"Kaur","headline":null,"bio":"Indie and film mixes. 200+ released songs. Remote delivery anywhere in India, revisions included.","city":"New Delhi","state":"Delhi","country":"India","roles":["guitarist","mixing_engineer","producer"],"instruments":[],"genres":["blues","rock","fusion"],"languages":["pa","hi","en"],"specialisations":[],"avatar_url":"https://images.unsplash.com/photo-151628044