","carnatic_classical"],"languages":["ta","te","ml"],"specialisations":[],"avatar_url":"https://images.unsplash.com/photo-1502823403499-6ccfcf4fb453?auto=format&fit=crop&w=400&q=80","cover_url":null,"availability":null,"experience_level":null,"links":{},"is_verified":true,"is_available":false,"trust_badges":[],"visibility":"public"},{"id":"565f053c-eacc-50cb-854d-d5d2bc06b64e","username":"ravi.deshmukh","display_name":"Ravi Deshmukh","first_name":"Ravi","last_name":"Deshmukh","headline":null,"bio":"Touring guitarist for 12 years. I sell and rent gear I have personally used on records and tours across India.","city":"Mumbai","state":"Maharashtra","country":"India","roles":["guitarist"],"instruments":[],"genres":[],"languages":[],"specialisations":[],"avatar_url":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=80","cover_url":null,"availability":null,"experience_level":null,"links":{},"is_verified":true,"is_available":true,"trust_badges":[],"visibility":"public"},{"id":"7d175f7d-88fd-5a16-ab64-48f852c60c7e","username":"soundhouse.studio","display_name":"SoundHouse Studio","first_name":"SoundHouse","last_name":"Studio","headline":null,"bio":"Studio-grade microphones, preamps and monitoring available for hire. Everything is serviced between rentals and delivered in flight cases.","city":"Mumbai","state":"Maharashtra","country":"India","roles":["studio","rental_provider"],"instruments":[],"genres":[],"languages":[],"specialisations":[],"avatar_url":"https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?auto=format&fit=crop&w=300&q=80","cover_url":null,"availability":null,"experience_level":null,"links":{},"is_verified":true,"is_available":true,"trust_badges":[],"visibility":"public"},{"id":"fc537d0d-0d31-5e6e-bc74-44d012f11f2d","username":"swaraj.instruments","display_name":"Swaraj Instruments","first_name":"Swaraj","last_name":"Instruments","headline":null,"bio":"Three generations of makers and restorers. Sitars, tanpuras, tablas and harmoniums, hand finished in Mumbai.","city":"Mumbai","state":"Maharashtra","country":"India","roles":["dealer","rental_provider"],"instruments":[],"genres":[],"languages":[],"specialisations":[],"avatar_url":"https://images.unsplash.com/photo-1511379938547-c1f69419868d?auto=format&fit=crop&w=300&q=80","cover_url":null,"availability":null,"experience_level":null,"links":{},"is_verified":true,"is_available":true,"trust_badges":[],"visibility":"public"},{"id":"269fb1ae-0e54-53ef-8b67-b59865b14427","username":"pulse.live.systems","display_name":"Pulse Live Systems","first_name":"Pulse","last_name":"Live Systems","headline":null,"bio":"PA systems, line arrays, monitors, DJ rigs and stage lighting with crew, delivery and on-site support anywhere in MMR.","city":"Mumbai","state":"Maharashtra","country":"India","roles":["rental_provider"],"instruments":[],"genres":[],"languages":[],"specialisations":[],"avatar_url":"https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&w=300&q=80","cover_url":null,"availability":null,"experience_level":null,"links":{},"is_verified":true,"is_available":true,"trust_badges":[],"visibility":"public"},{"id":"4e4558aa-e260-5be1-a1db-ef48eaa6133d","username":"krimson.avenue","display_name":"Krimson Avenue","first_name":"Krimson","last_name":"Avenue","headline":null,"bio":null,"city":"Bengaluru","state":"Karnataka","country":"India","roles":["studio"],"instruments":[],"genres":[],"languages":[],"specialisations":[],"avatar_url":"https://images.unsplash.com/photo-1519508234439-4f23643125c1?auto=format&fit=crop&w=600&q=80","cover_url":null,"availability":null,"experience_level":null,"links":{},"is_verified":false,"is_available":true,"trust_badges":[],"visibility":"public"},{"id":"77423851-8af1-54e3-b5ab-bb449187d213","username":"headroom.mastering","display_name":"Headroom Mastering","first_name":"Headroom","last_name":"Mastering","headline":null,"bio":"Attended and unattended mastering in a purpose-built ro