null,"links":{},"is_verified":true,"is_available":true,"trust_badges":[],"visibility":"public"}]$json$;
BEGIN
  INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, raw_app_meta_data,
    raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new,
    email_change, is_sso_user, is_anonymous)
  SELECT '00000000-0000-0000-0000-000000000000', r.id, 'authenticated', 'authenticated', NULL, NULL, '{}'::jsonb,
    jsonb_build_object('full_name', r.display_name, 'avatar_url', r.avatar_url), now(), now(),
    '', '', '', '', false, false
  FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, first_name text, last_name text, headline text, bio text, city text, state text, country text, roles text[], instruments text[], genres text[], languages text[], specialisations text[], avatar_url text, cover_url text, availability text, experience_level text, links jsonb, is_verified boolean, is_available boolean, trust_badges text[], visibility text)
  ON CONFLICT (id) DO NOTHING;

  -- on_auth_user_created has made a bare profile for each; fill it.
  INSERT INTO public.profiles (id, username, display_name, first_name, last_name, headline, bio, city, state, country, roles, instruments, genres, languages, specialisations, avatar_url, cover_url, availability, experience_level, links, is_verified, is_available, trust_badges, visibility, onboarding_complete)
  SELECT r.id, r.username, r.display_name, r.first_name, r.last_name, r.headline, r.bio, r.city, r.state, r.country, r.roles, r.instruments, r.genres, r.languages, r.specialisations, r.avatar_url, r.cover_url, r.availability, r.experience_level, r.links, r.is_verified, r.is_available, r.trust_badges, r.visibility, true
  FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, first_name text, last_name text, headline text, bio text, city text, state text, country text, roles text[], instruments text[], genres text[], languages text[], specialisations text[], avatar_url text, cover_url text, availability text, experience_level text, links jsonb, is_verified boolean, is_available boolean, trust_badges text[], visibility text)
  ON CONFLICT (id) DO UPDATE SET username = EXCLUDED.username, display_name = EXCLUDED.display_name, first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, headline = EXCLUDED.headline, bio = EXCLUDED.bio, city = EXCLUDED.city, state = EXCLUDED.state, country = EXCLUDED.country, roles = EXCLUDED.roles, instruments = EXCLUDED.instruments, genres = EXCLUDED.genres, languages = EXCLUDED.languages, specialisations = EXCLUDED.specialisations, avatar_url = EXCLUDED.avatar_url, cover_url = EXCLUDED.cover_url, availability = EXCLUDED.availability, experience_level = EXCLUDED.experience_level, links = EXCLUDED.links, is_verified = EXCLUDED.is_verified, is_available = EXCLUDED.is_available, trust_badges = EXCLUDED.trust_badges, visibility = EXCLUDED.visibility, onboarding_complete = true;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, first_name text, last_name text, headline text, bio text, city text, state text, country text, roles text[], instruments text[], genres text[], languages text[], specialisations text[], avatar_url text, cover_url text, availability text, experience_level text, links jsonb, is_verified boolean, is_available boolean, trust_badges text[], visibility text) JOIN public.profiles p ON p.id = r.id
      WHERE (p.username, p.display_name, p.first_name, p.last_name, p.headline, p.bio, p.city, p.state, p.country, p.roles, p.instruments, p.genres, p.languages, p.specialisations, p.avatar_url, p.cover_url, p.availability, p.experience_level, p.links, p.is_verified, p.is_available, p.trust_badges, p.visibility) IS NOT DISTINCT FROM (r.username, r.display_name, r.first_name, r.last_name, r.headline, r.bio, r.city, r.state, r.country, r.roles, r.instruments, r.genres, r.languages, r.specialisations, r.avatar_url, r.cover_url, r.availability, r.experience_level, r.links, r.is_verified, r.is_available, r.trust_badges, r.visibility))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'hardcoded people: stored profiles differ from the payload';
  END IF;
END
$import$;

-- profile_business (7 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"profile_id":"7d175f7d-88fd-5a16-ab64-48f852c60c7e","business_address":"Andheri West, Mumbai","logo_url":"https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?auto=format&fit=crop&w=300&q=80","hero_banner_url":null},{"profile_id":"fc537d0d-0d31-5e6e-bc74-44d012f11f2d","business_address":"Girgaon, Mumbai","logo_url":"https://images.unsplash.com/photo-1511379938547-c1f69419868d?auto=format&fit=crop&w=300&q=80","hero_banner_url":null},{"profile_id":"269fb1ae-0e54-53ef-8b67-b59865b14427","business_address":"Lower Parel, Mumbai","logo_url":"https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&w=300&q=80","hero_banner_url":null},{"profile_id":"4e4558aa-e260-5be1-a1db-ef48eaa6133d","business_address":"Koramangala, Bengaluru","logo_url":"https://images.unsplash.com/photo-1519508234439-4f23643125c1?auto=format&fit=crop&w=600&q=80","hero_banner_url":null},{"profile_id":"77423851-8af1-54e3-b5ab-bb449187d213","business_address":"Indiranagar, Bengaluru","logo_url":"https://images.unsplash.com/photo-1511379938547-c1f69419868d?auto=format&fit=crop&w=800&h=600&q=70","hero_banner_url":"https://images.unsplash.com/photo-1511379938547-c1f69419868d?auto=format&fit=crop&w=1200&h=800&q=70"},{"profile_id":"79661e0a-7cb0-5696-b16b-478b56381277","business_address":"Hauz Khas, Delhi","logo_url":"https://images.unsplash.com/photo-1520523839897-bd0b52f945a0?auto=format&fit=crop&w=800&h=600&q=70","hero_banner_url":"https://images.unsplash.com/photo-1520523839897-bd0b52f945a0?auto=format&fit=crop&w=1200&h=800&q=70"},{"profile_id":"18128ebd-c739-5c2e-b041-55496fcb1771","business_address":"Lower Parel, Mumbai","logo_url":"https://images.unsplash.com/photo-1514320291840-2e0a9bf2a9ae?auto=format&fit=crop&w=800&h=600&q=70","hero_banner_url":"https://images.unsplash.com/photo-1514320291840-2e0a9bf2a9ae?auto=format&fit=crop&w=1200&h=800&q=70"}]$json$;
BEGIN
