BEGIN
  INSERT INTO public.reviews (id, target_profile_id, author_name, author_org, context, rating, body, response, created_at)
  SELECT r.id, r.target_profile_id, r.author_name, r.author_org, r.context, r.rating, r.body, r.response, r.created_at
  FROM jsonb_to_recordset(payload) AS r(id uuid, target_profile_id uuid, author_name text, author_org text, context text, rating numeric, body text, response text, created_at timestamptz)
  ON CONFLICT (id) DO NOTHING;
END
$import$;

-- marketplace_listings: link the name-only sellers to their profiles
UPDATE public.marketplace_listings l SET seller_profile_id = s.profile_id
FROM (VALUES
  ('Ravi Deshmukh', '565f053c-eacc-50cb-854d-d5d2bc06b64e'::uuid),
  ('Swaraj Instruments', 'fc537d0d-0d31-5e6e-bc74-44d012f11f2d'::uuid),
  ('Meher Kaur', '0662ace1-0642-5590-832f-f55fa23438f1'::uuid),
